"""Generated by qprompt-a2a from qprompt graph 'CypressTestGeneration', workflow
'cypressFlow'.

DO NOT EDIT BY HAND -- regenerate via:
  qprompt-cli generate <file>.qprompt --format ir
  qprompt-a2a render <file>.ir.json 'cypressFlow'

Owns workflow routing (routes:/on_complete/step order) centrally, the same
role qprompt-langgraph's generated StateGraph.build_graph() plays -- each
agent stays a simple, single-purpose A2A service with no knowledge of what
calls it or what gets called next; only this process knows the graph shape.
It is deliberately a plain HTTP trigger, not an A2A agent itself: A2A models
communication *between* agents, and this is orchestration infrastructure
synthesized by codegen, not one of the graph's declared agents.
"""

from __future__ import annotations

import os
from typing import Any

from fastapi import FastAPI
from pydantic import BaseModel

from qprompt_a2a.runtime import call_agent

MAX_LOOPS = 4

AGENT_URLS: dict[str, str] = {
    'planTest': os.environ.get('PLAN_TEST_URL', 'http://plantest:8000'),
    'validatePlan': os.environ.get('VALIDATE_PLAN_URL', 'http://validateplan:8000'),
    'genCode': os.environ.get('GEN_CODE_URL', 'http://gencode:8000'),
    'lint': os.environ.get('LINT_URL', 'http://lint:8000'),
    'debugError': os.environ.get('DEBUG_ERROR_URL', 'http://debugerror:8000'),
    'runTests': os.environ.get('RUN_TESTS_URL', 'http://runtests:8000'),
}

ENTRY_POINT = 'planTest'


def _route_validatePlan(state: dict[str, Any]) -> str:
    if state.get('failed'):
        return 'planTest'
    if  not state.get('failed'):
        return 'genCode'
    return "END"

def _route_lint(state: dict[str, Any]) -> str:
    if state.get('failed'):
        return 'debugError'
    if  not state.get('failed'):
        return 'runTests'
    return "END"

def _route_runTests(state: dict[str, Any]) -> str:
    if state.get('failed'):
        return 'debugError'
    return "END"


_DIRECT_EDGES: dict[str, str] = {
    'planTest': 'validatePlan',
    'genCode': 'lint',
    'debugError': 'lint',
}


async def run_workflow(inputs: dict[str, Any]) -> dict[str, Any]:
    state: dict[str, Any] = dict(inputs)
    current = ENTRY_POINT
    loops = 0

    while current != "END":
        state.update(await call_agent(AGENT_URLS[current], state))

        if current == 'validatePlan':
            loops += 1
            if loops > MAX_LOOPS:
                break
            current = _route_validatePlan(state)
            continue
        if current == 'lint':
            loops += 1
            if loops > MAX_LOOPS:
                break
            current = _route_lint(state)
            continue
        if current == 'runTests':
            loops += 1
            if loops > MAX_LOOPS:
                break
            current = _route_runTests(state)
            continue
        current = _DIRECT_EDGES.get(current, "END")

    return state


app = FastAPI()


class RunRequest(BaseModel):
    inputs: dict[str, Any]


@app.post("/run")
async def run(request: RunRequest) -> dict[str, Any]:
    return await run_workflow(request.inputs)


if __name__ == "__main__":
    import uvicorn

    uvicorn.run(app, host="0.0.0.0", port=int(os.environ.get("PORT", 8000)))
